 t('<b>Measures</b>', '<b>acceptance over tolerance</b>', '<b>scientific temper</b> and constitutional morality', '<b>rule of law</b> against violence and discrimination', '<b>inclusive development</b>', '<b>constructive social work</b> like Gandhi\'s'),
